INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I001', 'scientific_wording', '{"type":"scientific_wording","source_statement":"酸素がミトコンドリアでエネルギー（ATP）に変わる","editorial_action":"酸素は、細胞が栄養からATPをつくる過程で使われます。","proposed_wording":"酸素は、細胞が栄養からATPをつくる過程で使われます。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P01']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I002', 'terminology', '{"type":"terminology","source_statement":"内呼吸（Cellular Respiration）","editorial_action":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。","proposed_wording":"「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P02']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I003', 'unsupported_quantity', '{"type":"unsupported_quantity","source_statement":"1分間にATPを約2〜3kg産生","editorial_action":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。","proposed_wording":"ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P07']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I004', 'overgeneralization', '{"type":"overgeneralization","source_statement":"すべての細胞でミトコンドリアがATPを作る","editorial_action":"多くの細胞では、ミトコンドリアがATPの産生に関わります。","proposed_wording":"多くの細胞では、ミトコンドリアがATPの産生に関わります。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P07']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I005', 'arithmetic', '{"type":"arithmetic","source_statement":"37兆個（37,000億個）","editorial_action":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。","proposed_wording":"37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P07']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I006', 'unsafe_scoring', '{"type":"unsafe_scoring","source_statement":"呼吸数8回以下をとても良いとする評価表","editorial_action":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。","proposed_wording":"安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P08']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I007', 'overgeneralization', '{"type":"overgeneralization","source_statement":"CO₂がなければ呼吸できない／ヨガはCO₂耐性で心身を安定","editorial_action":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。","proposed_wording":"CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P06']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I008', 'citation_version', '{"type":"citation_version","source_statement":"引用先CYPにはシータリーが明記されている","editorial_action":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。","proposed_wording":"引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', ARRAY['P19','P24']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I009', 'text_image_difference', '{"type":"text_image_difference","source_statement":"ブラーマリーのイラストは耳に手を当てるが簡易版の本文手順にはない","editorial_action":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。","proposed_wording":"簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P20']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I010', 'audience_conflict', '{"type":"audience_conflict","source_statement":"初心者の参考回数と、初心者は実践しないという教材方針が併記","editorial_action":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。","proposed_wording":"この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P21','P22']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I011', 'citation_scope', '{"type":"citation_scope","source_statement":"妊娠中・月経中をCYPのカパラバティ禁忌として列挙","editorial_action":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。","proposed_wording":"該当する注意は「本教材の方針」として記載し、CYPのカパラバティ節にあると断定しない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', ARRAY['P22']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I012', 'protocol_variation', '{"type":"protocol_variation","source_statement":"4-7-8で保息を短縮または省略","editorial_action":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。","proposed_wording":"保息の長さや有無を変える場合は、別の変種として名称・手順・出典を記載する。確定前の手順は案内しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P25']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I013', 'efficacy_claim', '{"type":"efficacy_claim","source_statement":"睡眠・集中・免疫・健康寿命などの広い改善表現","editorial_action":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。","proposed_wording":"この教材では、睡眠・集中などに関連する学習テーマとして呼吸を紹介します。個人の改善を保証する表現は削る。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P10','P11','P24']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I014', 'product_copy', '{"type":"product_copy","source_statement":"AIが最適な改善提案／QRコード誘導","editorial_action":"QRとAIの紹介は案内欄に分ける。接続先・機能が確認できた範囲だけを説明する。","proposed_wording":"QRとAIの紹介は案内欄に分ける。接続先・機能が確認できた範囲だけを説明する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P11']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I015', 'editorial_review', '{"type":"editorial_review","source_statement":"副鼻腔のNOから集中力・免疫・運動効果へつなげる説明","editorial_action":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。","proposed_wording":"副鼻腔の構造の説明を残し、集中力・免疫・運動能力への効果は根拠確認まで別欄で保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P031']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I016', 'editorial_review', '{"type":"editorial_review","source_statement":"吐くときは内肋間筋が収縮、という一律の図示","editorial_action":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。","proposed_wording":"安静時に吐く場合と、力を入れて吐く場合を分けて説明する。筋肉名と図の動作は監修後に確定する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P036']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I017', 'source_numbering', '{"type":"source_numbering","source_statement":"第3章ファイル内に第2章・P12〜P20の表示がある","editorial_action":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。","proposed_wording":"ファイル上の章番号と図中の章番号を別に保存し、正式な章割りが決まった後に見出しを統一する。","remaining_work":"章番号・掲載画像の具体的な選択は未確定"}', 'editorial_policy_applied', ARRAY['P037','P038']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I018', 'editorial_review', '{"type":"editorial_review","source_statement":"深くゆっくり吸うほど効率がよいという一般化","editorial_action":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。","proposed_wording":"この図は、死腔と肺胞換気を理解するための計算例です。呼吸を大きくする練習の目標値ではありません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P038']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I019', 'editorial_review', '{"type":"editorial_review","source_statement":"SpO₂の範囲だけで健康・軽い不調等を決める表","editorial_action":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。","proposed_wording":"SpO₂の数値だけで健康状態を採点しません。測定条件や症状も含めて扱います。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P041']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I020', 'editorial_review', '{"type":"editorial_review","source_statement":"ATPは1日に体重の約100倍作られる","editorial_action":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。","proposed_wording":"ATPの再利用の説明を残し、「1日に体重の約100倍」の数値は根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P043']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I021', 'scientific_review', '{"type":"scientific_review","source_statement":"解糖をミトコンドリア内に配置／酸素がなければ糖はエネルギーにならない","editorial_action":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。","proposed_wording":"糖からエネルギーを取り出す過程は複数あります。反応の場所と酸素の必要性を分けた図に描き直し、監修を受ける。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P044']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I022', 'timing_variants', '{"type":"timing_variants","source_statement":"第6章の図では呼気後に自然に待つ1〜2秒を追加し、回数換算の表記にも不一致がある","editorial_action":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。","proposed_wording":"基本手順と図中の「自然な間」を別記する。記載のない固定保息や毎分回数へ換算しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P081']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I023', 'timing_variants', '{"type":"timing_variants","source_statement":"ボックス呼吸の回数は第6章4〜5、第7章3〜5。やさしい版は等間隔ではない","editorial_action":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。","proposed_wording":"第6章：4〜5サイクル。第7章：3〜5セット。やさしい版は別の変種。各出典の手順を独立して表示する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P082','P083']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I024', 'attribution', '{"type":"attribution","source_statement":"ボックス呼吸をNavy SEALsが考案したという記載","editorial_action":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。","proposed_wording":"ボックス呼吸を現代呼吸法として紹介する。「Navy SEALsが考案」は起源資料が確認できるまで削除候補にする。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', ARRAY['P082']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I025', 'ambiguous_instruction', '{"type":"ambiguous_instruction","source_statement":"4・7・8呼吸法に「7秒間、息を止めずにキープ」と記載","editorial_action":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。","proposed_wording":"「7秒間、息を止めずにキープ」の意図が確定するまで、この手順の実践案内を保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P085']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I026', 'distinct_variant', '{"type":"distinct_variant","source_statement":"第8章の「4-7-8呼吸のやさしい版」は4秒吸う・7〜8秒吐く、保息なし","editorial_action":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。","proposed_wording":"名称案：就寝前のやさしい呼吸（第8章・保息なし）。原図の4秒吸う・7〜8秒吐くを記録し、7秒の保息は追加しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P094']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I027', 'name_conflict', '{"type":"name_conflict","source_statement":"10-4の実践2見出しが「食前の休息呼吸」だが、手順は食後、第10章一覧も食後","editorial_action":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","proposed_wording":"見出し案：「食後の休息呼吸」。本文と第10章一覧に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P105','P106']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I028', 'duplicate_layout', '{"type":"duplicate_layout","source_statement":"第13章に13-4の図版が2種類ある","editorial_action":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","proposed_wording":"13-4の2図版は両方を保存する。正式掲載に使う1点を選び、もう1点は旧案として区別する。","remaining_work":"章番号・掲載画像の具体的な選択は未確定"}', 'editorial_policy_applied', ARRAY['P112','P113']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I029', 'timing_variants', '{"type":"timing_variants","source_statement":"第14章は同名の基本技法と秒数・吐き方が異なる","editorial_action":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","proposed_wording":"第4部導入の基本手順と第14章の場面別変種を別表示する。秒数・吐き方を混ぜない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P107','P108','P117','P118']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I030', 'scientific_review', '{"type":"scientific_review","source_statement":"空気の経路に副鼻腔・血液・細胞を直列表示","editorial_action":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","proposed_wording":"空気の通路と、肺胞から血液・細胞への酸素の運搬を2段に分けて図示する。副鼻腔を必須の直列通過点にしない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P149']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I031', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"一回の呼吸は約0.5秒／図の0.9秒","editorial_action":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","proposed_wording":"一呼吸の周期と肺まで空気が移動する時間を区別する。「約0.5秒」「0.9秒」は定義・根拠確認まで掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P151']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I032', 'scientific_review', '{"type":"scientific_review","source_statement":"肺には筋肉がありません／肺は動かない","editorial_action":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","proposed_wording":"肺は、自分で筋肉を縮めて空気を吸い込む器官ではありません。横隔膜や肋骨の間の筋肉が働いて胸の中の空間を広げると、それに伴って肺が膨らみ、空気が入ります。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P152']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I033', 'scientific_review', '{"type":"scientific_review","source_statement":"肋骨運動の名称と方向、全肋骨が胸骨につながる図","editorial_action":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","proposed_wording":"肋骨の動きの名称・方向・胸骨との接続先を監修し、図と本文を同時に修正する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P153']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I034', 'scientific_review', '{"type":"scientific_review","source_statement":"呼気時の胸腔内圧を一律に陽圧として表す","editorial_action":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","proposed_wording":"図に圧の測定部位・基準・単位・呼吸条件を明記する。確認前は「呼気時の胸腔内圧は陽圧」という一律の説明を外す。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P154','P155']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I035', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"SpO₂の章内の区分不一致","editorial_action":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","proposed_wording":"章内のSpO₂区分表は回答用から外し、統一する医学的な基準・対象・条件を監修者に確認する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P158']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I036', 'scientific_review', '{"type":"scientific_review","source_statement":"酸素タクシーは満員で出発、細胞で全席空く","editorial_action":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","proposed_wording":"酸素タクシーは、結合部位を学ぶためのたとえです。必ず満席で出発し、全部を降ろすという意味ではありません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P163']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I037', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"肺胞数3〜5億と2億5000万の違い","editorial_action":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","proposed_wording":"肺胞数は出典と条件が確認できた数値のみを記載する。確認前は「多数の肺胞」という説明にとどめる。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P156','P164']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I038', 'internal_arithmetic', '{"type":"internal_arithmetic","source_statement":"37兆個の細胞と37兆個のミトコンドリアの混同","editorial_action":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","proposed_wording":"細胞数とミトコンドリア数は分けて記載する。計算例として37兆×1.5µmを使うなら55,500km。ただし実際の総数・長さの説明としては未確定。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P168','P170']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I039', 'scientific_review', '{"type":"scientific_review","source_statement":"運動・呼吸・食品・栄養補助成分でミトコンドリアが増えるという一覧","editorial_action":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","proposed_wording":"運動・睡眠・食事などの生活要素を紹介する。個別成分でミトコンドリアが増える、若返るという断定や摂取指示は掲載しない。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P171']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I040', 'scientific_review', '{"type":"scientific_review","source_statement":"疲労等のすべての原因はATP不足・低酸素","editorial_action":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","proposed_wording":"この図だけで、本人の疲労や眠気の原因をATP不足・低酸素と判断することはできません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P159','P172','P211']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I041', 'scientific_review', '{"type":"scientific_review","source_statement":"吸気＝交感、呼気＝副交感の二値スイッチ／唯一・最も確実","editorial_action":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","proposed_wording":"呼吸と自律神経の関係を学びます。吸気・呼気を全身の神経状態が完全に切り替わるスイッチとして説明しません。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P180','P184','P185']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I042', 'scientific_review', '{"type":"scientific_review","source_statement":"グラフの「心拍（R-R間隔）」","editorial_action":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","proposed_wording":"「心拍数」と「R-R間隔」を別の量として表示する。軸名・単位・波形の向きを確認して図を差し替える。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P185']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I043', 'citation_review', '{"type":"citation_review","source_statement":"Frontiers・NCBI・PMC・med.navy.mil等だけの引用","editorial_action":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","proposed_wording":"引用欄に著者・資料名・発行年・個別URL・参照箇所を記載する。機関名だけの引用は根拠の確定に使わない。","remaining_work":"引用元の特定・照合が必要"}', 'editorial_policy_applied', ARRAY['P174','P183','P184','P187','P207']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I044', 'internal_inconsistency', '{"type":"internal_inconsistency","source_statement":"導入4-4-6〜8-4秒とボックス4-4-4-4秒の差","editorial_action":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","proposed_wording":"等時間のボックス呼吸と導入図の不等時間例を別表示する。導入例の名称が決まるまで実践配信は保留する。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P186','P187','P188']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I045', 'label_correction', '{"type":"label_correction","source_statement":"呼吸カウントの図3人目が吐いて1、本文は吸って2","editorial_action":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","proposed_wording":"図の順序案：吸って1 → 吐いて1 → 吸って2 → 吐いて2。3人目のラベルを本文に合わせる。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P197']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I046', 'classification_update', '{"type":"classification_update","source_statement":"NREM睡眠をステージ1〜4で記載","editorial_action":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","proposed_wording":"NREM睡眠をN1・N2・N3の3段階に整理する。図の配置と本文をまとめて更新する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P206']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I047', 'scientific_review', '{"type":"scientific_review","source_statement":"NOから脳・免疫・いびき・睡眠への効果をつなぐ図","editorial_action":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","proposed_wording":"鼻の構造・NOの説明と、脳・免疫・いびき・睡眠への効果の主張を別に扱う。効能の矢印は根拠確認まで保留する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P196','P208']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I048', 'scientific_review', '{"type":"scientific_review","source_statement":"深呼吸で代謝・血流・老廃物排出・消化排泄が一律に改善","editorial_action":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","proposed_wording":"呼吸と日常のコンディショニングの関係を学びます。「誰でも一律に代謝・血流・排出・消化が改善する」という保証は削る。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P213','P215','P216']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I049', 'scientific_review', '{"type":"scientific_review","source_statement":"声の質のすべてが呼吸で決まる／胸・頭を共鳴腔として図示","editorial_action":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","proposed_wording":"声は、呼吸・声帯・共鳴・発音などが関係して生まれます。胸や頭に感じる響きと、解剖学的な共鳴腔は区別して監修する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P223']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I050', 'editorial_metadata', '{"type":"editorial_metadata","source_statement":"外部監修を入れる場合の配置候補","editorial_action":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","proposed_wording":"「監修候補・未依頼」という制作メモとして保存する。教材本文やAIの回答に監修済みと表示しない。","remaining_work":"原図の修正は未実施"}', 'editorial_policy_applied', ARRAY['P224']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_issues (issue_id, title, description, status, related_entry_ids) VALUES ('I051', 'terminology_review', '{"type":"terminology_review","source_statement":"アシュタンガの八支則と流派名の関係","editorial_action":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","proposed_wording":"八支則を意味する用語としてのアシュタンガと、現代の実践スタイルの名称を分け、歴史・用語の監修後に確定する。","remaining_work":"専門監修が必要"}', 'editorial_policy_applied', ARRAY['P231']::text[]) ON CONFLICT (issue_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC001', 'I001', '酸素は、細胞が栄養からATPをつくる過程で使われます。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC002', 'I002', '「内呼吸」と「細胞呼吸」の用語欄を分け、それぞれの定義を監修後に掲載する。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC003', 'I003', 'ATPの産生・利用は繰り返されています。原稿の「1分間に約2〜3kg」は根拠確認まで掲載しない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC004', 'I004', '多くの細胞では、ミトコンドリアがATPの産生に関わります。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC005', 'I005', '37兆個（370,000億個）。※単位換算のみの修正案。37兆個という生物学的な数値の妥当性とは別。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC006', 'I006', '安静時の呼吸数を記録し、そのときの状態と一緒に振り返りましょう。回数だけで「良い・悪い」を採点しません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC007', 'I007', 'CO₂は呼吸調節に関わります。「CO₂だけが呼吸を決める」「CO₂耐性がヨガの効果を確定する」という説明は削除候補にする。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC008', 'I008', '引用するCYPの版・発行年・ページを明記する。シータリーの掲載を確認できるまでは「このCYPに明記」と書かない。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC009', 'I009', '簡易版の本文に合わせ、耳を塞ぐ動作は手順に追加しない。イラストも本文と一致させる。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;
INSERT INTO breath_manager_v5.bm5_editorial_corrections (correction_id, issue_id, description, rule_text, applied) VALUES ('EC010', 'I010', 'この教材では、初心者はカパラバティの特徴と注意点を学びます。実践の回数は案内しません。', 'ユーザー「肺の説明は直前に示した意図、あとは修正通りでお願いします」', true) ON CONFLICT (correction_id) DO NOTHING;